seq="".join(l.strip() for l in open("region.fasta") if not l.startswith(">"))
n=len(seq)
comp={'A':'T','T':'A','G':'C','C':'G'}
r=lambda s:''.join(comp[c] for c in reversed(s))

# ---- inverted repeat scan with seed k=6 ----
k=6
pos={}
for i in range(n-k+1):
    pos.setdefault(seq[i:i+k],[]).append(i)
pairs=[]
for i in range(n-k+1):
    for j in pos.get(r(seq[i:i+k]),[]):
        if j > i+k-1:
            pairs.append((i,j))
print("seed pairs:",len(pairs))
cands=[]
for i,j in pairs:
    L=i; R=j+k-1    # arms: left seq[L..], right revcomp of seq[R]
    mm=0; span=k
    maxlen=80
    while L-1>=0 and R+1<n and (i-L)<maxlen:
        if seq[L-1]==comp[seq[R+1]]:
            L-=1; R+=1; span+=1
        else:
            mm+=1; L-=1; R+=1; span+=1
            if mm > 0.25*span+1 and span>=12: break
    loop = j - (i+1) + 0   # bases between the two arms (approx)
    cands.append((span, mm, i, j, loop))
cands.sort(key=lambda x:(-x[0], x[1]))
for c in cands[:20]:
    span,mm,i,j,loop=c
    print("armlen",span,"mm",mm,"left",i,"rightEnd",j+k-1,"loop",j- i-k, "->",seq[i:i+span],"|",r(seq[j+k-span:j+k]))
