codon={b1+b2+b3:aas[i*16+j*4+k] for i,b1 in enumerate(bases) for j,b2 in enumerate(bases) for k,b3 in enumerate(bases)}
def translate(s,f): return "".join(codon[s[i:i+3]] for i in range(f,len(s)-2,3))
motifs={
 "YREK-like":r"Y..R...E.{4,8}K",
 "DDE-ish ":r"D.{58,72}[DE].{30,45}D",
 "RHRY":r"R.H.R.Y",
 "GDGxNDxP":r"GDG.ND.P",
 "DKTGTLT":r"DKTGTLT",
 "TGES":r"TGE[ST]",
 "HTH1":r"[LIV]..[LIV].{3}[LIV]..[LIV]",
 "GKT/S P-loop":r"[AG].{4}GK[ST]",
 "DKxxD":r"DKTGTLT",
}
for name,p in motifs.items():
    pat=re.compile(p)
    print("###",name)
    for strand,s in [("+",seq),("-",rc(seq))]:
        for f in range(3):
            tr=translate(s,f)
            for m in pat.finditer(tr):
                pos=m.start()*3+f+1
                if strand=="-": pos=n-pos+1
